import json
d=json.load(open('pd.json'))
def walk(n, out):
    if isinstance(n, dict):
        t=n.get('type')
        if t=='text': out.append(n.get('text',''))
        elif t=='codeVoice': out.append('\`'+n.get('code','')+'\`')
        elif t in ('paragraph','heading','aside','listItem','unorderedList','orderedList','links'):
            pass
        for k,v in n.items():
            if k in ('text','code'): continue
            walk(v,out)
        if t in ('paragraph','listItem'): out.append('\n')
        if t=='heading': out.append('\n## '+n.get('text','')+'\n')
    elif isinstance(n,list):
        for i in n: walk(i,out)
out=[]
walk(d.get('primaryContentSections',[]),out)
walk(d.get('abstract',[]),out)
print(''.join(out))
